```javascript
 
<!DOCTYPE html>
 
<html>
 
<head>
    <meta charset="utf-8" />
    <title>TicTacToe</title>
</head>
 
<body>
    <canvas id="canvas" width="400" height="400"></canvas>
 
    <script>
        //All helper functions
        isBetween = (num, a, b) => {
            return num >= a && num <= b;
        }
 
        randInt = (low, high) => {
