<!DOCTYPE html>
 
<html>
 
<head>
    <meta charset="utf-8" />
    <title>TicTacToe</title>
</head>
 
<body>
    <canvas id="canvas" width="400" height="400"></canvas>
 
    <script>
        //All helper functions
        isBetween = (num, a, b) => {
            return num >= a && num <= b;
        }
 
        randInt = (low, high) => {
            return Math.floor(Math.random() * (high - low + 1)) + low;
        }
 
        choice = arr => {
            return arr[randInt(0, arr.length - 1)];
        }
 
        //Checks if every value in an array equals an item
        equals = (arr, item) => {
            return arr.filter(a => {
                return a === item;
            }).length === arr.length;
        }
 
        //Returns number of items in array that equal an item
        equallen = (arr, item) => {
            return arr.filter(a => {
                return a === item;
            }).length
        }
 
        //Checks if any value in the array equals an item
        equalanyof = (arr, item) => {
            return equallen(arr, item) > 0;
        }
 
        //Should be scalable, but it uses default elements for calculations and tracking
