# Module: calculus.py
 
import enum
 
class entry_not_found(Exception):
   """Raised when an entry is not found in a collection"""
   pass
 
class entry_already_exists(Exception):
   """Raised when an entry already exists in a collection"""
   pass
 
class state(enum.Enum):
   header = 0
   left_high = 1
   right_high = 2
   balanced = 3
 
class direction(enum.Enum):
   from_left = 0
   from_right = 1
 
from abc import ABC, abstractmethod
 
class comparer(ABC):
 
    @abstractmethod
    def compare(self,t):
        pass
 
class node(comparer):
 
    def __init__(self):
        self.parent = None
        self.left = self
        self.right = self
        self.balance = state.header
 
    def compare(self,t):
        if self.key < t:
             return -1
        elif t < self.key:
             return 1
        else:
             return 0
 
    def is_header(self):
        return self.balance == state.header
 
    def length(self):
        if self != None:
           if self.left != None:
              left = self.left.length()
           else:
              left = 0
           if self.right != None:   
              right = self.right.length()
           else:
              right = 0
 
           return left + right + 1
        else:
           return 0
 
    def rotate_left(self):
